-- MP-0024: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='pas' and type='party') then raise exception 'MP-0024: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='perikatan-nasional' and type='alliance') then raise exception 'MP-0024: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='umno' and type='party') then raise exception 'MP-0024: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('jamaludin-yahya','nordin-ahmad-ismail','ramli-mohd-nor') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0024: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('pasir salak','lumut','cameron highlands') and slug not in ('jamaludin-yahya','nordin-ahmad-ismail','ramli-mohd-nor')) then raise exception 'MP-0024: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0024:%' and (m.source_type <> 'editorial' or e.slug not in ('jamaludin-yahya','nordin-ahmad-ismail','ramli-mohd-nor') or m.import_key not like 'MP-0024:' || e.slug || ':%')) then raise exception 'MP-0024: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'jamaludin-yahya','Jamaludin Yahya','opposition','Member of the Dewan Rakyat','Pasir Salak','Perak','Jamaludin Yahya represents Pasir Salak, Perak, in the Dewan Rakyat. A PAS member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4112','/portraits/jamaludin-yahya.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P073.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4112"}, {"label": "PAS · parliamentary representatives", "url": "https://pas.org.my/ahli-parlimen-pas-pru-ke-15/"}]'::jsonb from public.entities parent where parent.slug='pas' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'nordin-ahmad-ismail','Nordin Ahmad Ismail','opposition','Member of the Dewan Rakyat','Lumut','Perak','Nordin Ahmad Ismail represents Lumut, Perak, in the Dewan Rakyat. Parliament records affiliation with Perikatan Nasional (PN).','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4113','/portraits/nordin-ahmad-ismail.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P074.jpeg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4113"}, {"label": "Parliament · current Dewan Rakyat directory", "url": "https://www.parlimen.gov.my/ahli-dewan.html?uweb=dr"}]'::jsonb from public.entities parent where parent.slug='perikatan-nasional' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'ramli-mohd-nor','Ramli Mohd Nor','government','Deputy Speaker of the Dewan Rakyat; Member of the Dewan Rakyat','Cameron Highlands','Pahang','Ramli Mohd Nor represents Cameron Highlands, Pahang, in the Dewan Rakyat. Current role: Deputy Speaker of the Dewan Rakyat; Member of the Dewan Rakyat. A UMNO member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4117','/portraits/ramli-mohd-nor.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P078.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4117"}, {"label": "UMNO · current supreme council member, 23 August 2026", "url": "https://umno-online.my/2026/08/23/pendidikan-bina-masa-depan-anak-orang-asli-ramli/"}, {"label": "Parliament · Deputy Speaker role", "url": "https://www.parlimen.gov.my/mobile/profile-ahli.html?id=4117&lang=en&uweb=dr"}]'::jsonb from public.entities parent where parent.slug='umno' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('jamaludin-yahya','nordin-ahmad-ismail','ramli-mohd-nor') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0024: concurrent ownership or identity change'; end if; end $$;

commit;
